def rawSignedSimplexMoment (n : ℕ) (μ : Measure (Fin n → ℝ)) (g : (Fin n → ℝ) → ℝ) :
    RawRationalChains (Fin n → ℝ) n →ₗ[ℚ] ℝ :=
  Finsupp.linearCombination ℚ (fun σ => ∫ y, signedSimplexCount n σ y * g y ∂μ)

